function convertGoogleSerialToPeriod(value) {
  if (value === null || value === undefined || value === '') return '';

  const stringValue = String(value).trim();

  if (/^\d{4}-\d{2}$/.test(stringValue)) {
    return stringValue;
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(stringValue)) {
    return stringValue.slice(0, 7);
  }

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(stringValue)) {
    const [day, month, year] = stringValue.split('/');
    return `${year}-${String(month).padStart(2, '0')}`;
  }

  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(stringValue)) {
    const [day, month, year] = stringValue.split('-');
    return `${year}-${String(month).padStart(2, '0')}`;
  }

  if (!isNaN(stringValue)) {
    const serial = Number(stringValue);
    const utcDays = Math.floor(serial - 25569);
    const utcValue = utcDays * 86400;
    const date = new Date(utcValue * 1000);

    const y = date.getUTCFullYear();
    const m = String(date.getUTCMonth() + 1).padStart(2, '0');

    return `${y}-${m}`;
  }

  return stringValue;
}

