const sourceItems = items.map(item => item.json);
const groups = {};

for (const row of sourceItems) {
  const id = String(row.ID_Karyawan || '').trim();
  const nama = String(row.Nama || '').trim();
  const periode = String(row.Periode || '').trim();
  const role = String(row.Penilai_Role || '').trim();

  if (!id || !nama || !periode || !role) continue;

  const groupKey = `${id}_${periode}`;

  if (!groups[groupKey]) {
    groups[groupKey] = {
      ID_Karyawan: id,
      Nama: nama,
      Divisi: row.Divisi || '',
      Jabatan: row.Jabatan || '',
      Periode: periode,
      evaluasi: []
    };
  }

  groups[groupKey].evaluasi.push({
    nama_penilai: row.Nama_Penilai || '',
    role_penilai: role,
    skor_performa_umum: row.Skor || 0,
    kedisiplinan: row.Kedisiplinan || 0,
    kualitas_kerja: row.Kualitas_Kerja || 0,
    komunikasi: row.Komunikasi || 0,
    kerja_sama_tim: row.Kerja_Sama_Tim || 0,
    tanggung_jawab: row.Tanggung_Jawab || 0,
    komentar_umum: row.Komentar || '',
    kekuatan_karyawan: row.Kekuatan_Karyawan || '',
    area_pengembangan: row.Area_Pengembangan || '',
    rekomendasi_tindakan: row.Rekomendasi_Tindakan || ''
  });
}

return Object.values(groups).map(employee => {
  const roles = [
    ...new Set(
      employee.evaluasi.map(e =>
        String(e.role_penilai || '').trim().toLowerCase()
      )
    )
  ];

  const adaAtasan = roles.includes('atasan');
  const adaRekan = roles.includes('rekan');
  const adaBawahan = roles.includes('bawahan');

  return {
    json: {
      ...employee,
      total_penilai: employee.evaluasi.length,
      role_tersedia: roles,
      data_lengkap: adaAtasan && adaRekan && adaBawahan,
      debug: {
        total_input_dari_normalize: sourceItems.length,
        role_terbaca: roles
      }
    }
  };
});

